<script setup lang="ts">
import { computed } from 'vue';
import type { DavSnapshot } from '@/lib/backend/types';
const props=defineProps<{snapshot:DavSnapshot;disabled?:boolean}>(); const emit=defineEmits<{restore:[id:string]}>();
const status:Record<DavSnapshot['state'],string>={structurally_complete:'结构完整，待完整校验',missing_manifest:'缺少清单',invalid_manifest:'清单无法解析',unsupported_format:'格式不支持',incomplete:'上传未完成：缺少完成标记',missing_connections:'缺少连接资料包',missing_credentials:'缺少凭据包',integrity_mismatch:'文件校验不一致',unavailable:'暂时不可检查',legacy:'旧格式备份，待完整校验',legacy_unconfirmed:'旧格式待确认'};
const inferredTime=computed(()=>props.snapshot.source==='legacy'||props.snapshot.appVersion===null||['missing_manifest','invalid_manifest','unsupported_format','legacy_unconfirmed'].includes(props.snapshot.state));
const time=computed(()=>{if(!props.snapshot.createdAt)return '时间未知';const value=new Date(props.snapshot.createdAt);return Number.isNaN(value.valueOf())?'时间未知':new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'medium',timeZoneName:undefined}).format(value)+`（${Intl.DateTimeFormat().resolvedOptions().timeZone}）`;});
function size(value:number|null){if(value===null)return '大小未知';if(value<1024)return `${value} bytes`;if(value<1024*1024)return `${(value/1024).toFixed(1)} KiB`;return `${(value/1024/1024).toFixed(2)} MiB`;}
</script>
<template><article class="snapshot-card" :class="{'snapshot-card--unavailable':!snapshot.restorable}" :data-snapshot-id="snapshot.id"><div class="snapshot-card__body"><h4>{{snapshot.name || snapshot.directory}}</h4><p class="snapshot-card__time"><span v-if="snapshot.createdAt && inferredTime">目录时间（推算）：</span>{{time}}</p><p>应用版本{{snapshot.appVersion || '未知'}} · 格式版本{{snapshot.formatVersion ?? '未知'}} · {{size(snapshot.sizeBytes)}} · {{snapshot.protection==='encrypted'?'口令加密':snapshot.protection==='none'?'未加密':'保护方式未知'}}</p><p>{{snapshot.containsCredentials===null?'凭据情况未知':snapshot.containsCredentials?'包含已保存凭据':'不含已保存凭据'}}<span v-if="snapshot.source==='legacy'"> · 旧格式兼容</span></p><p class="snapshot-card__state" :class="{'snapshot-card__state--error':!snapshot.restorable}">{{status[snapshot.state]}}</p><p v-if="snapshot.reason" class="snapshot-card__reason">{{snapshot.reason}}</p></div><button type="button" data-test="restore-snapshot" :disabled="disabled || !snapshot.restorable" @click="emit('restore',snapshot.id)">恢复备份</button></article></template>
<style scoped>
.snapshot-card{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:17px 18px;border:1px solid var(--border);border-radius:8px;background:var(--chrome)}.snapshot-card__body{min-width:0}.snapshot-card h4{margin:0 0 7px;font-size:14px;color:var(--foreground);overflow-wrap:anywhere}.snapshot-card p{margin:4px 0;color:var(--muted);font-size:12px;line-height:1.5}.snapshot-card .snapshot-card__time{font-size:11px;color:var(--muted)}.snapshot-card .snapshot-card__state{color:var(--accent)}.snapshot-card .snapshot-card__state--error{color:var(--danger)}.snapshot-card .snapshot-card__reason{font-style:italic;overflow-wrap:anywhere}.snapshot-card button{flex:none;white-space:nowrap}.snapshot-card--unavailable{background:var(--chrome)}@media(max-width:640px){.snapshot-card{align-items:flex-start;flex-direction:column;gap:12px}.snapshot-card button{align-self:flex-end}}
</style>
